tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'EOF'
import { deepStrictEqual, strictEqual } from 'node:assert/strict';
import { readParcel } from './modules/import/src/public.ts';
import { forChute } from './modules/import/src/consumer.ts';

for (const [prefix, zone] of [['N', 'north'], ['S', 'south']]) {
  for (let position = 0; position <= 999; position++) {
    const label = prefix + '-' + String(position).padStart(3, '0');
    deepStrictEqual(readParcel(label), { zone, position });
    strictEqual(forChute(label), zone + ':' + position);
  }
}
for (const input of [{ deferred: true }, 'E-007', 'N-07', 'S-1000', '', null, 7]) {
  strictEqual(readParcel(input), null);
  strictEqual(forChute(input), '');
}
console.log('Passed: 2,000 approved labels and 7 rejected inputs through readParcel and forChute');
EOF
set -e
test \""'$(npm run --silent read -- '"'\"N-007\"')\" = '{\"zone\":\"north\",\"position\":7}'
test \""'$(npm run --silent read -- '"'\"S-123\"')\" = '{\"zone\":\"south\",\"position\":123}'
test \""'$(npm run --silent read -- '"'{\"deferred\":true}')\" = 'null'
printf '%s\\n' 'Passed: public CLI for both zones and deferred input'"

changed_file_contents.modules/import/src/public.ts:
import { labelSchema } from "./protocol.ts";

type Parsed = Extract<ReturnType<typeof labelSchema.decode>, { ok: true }>["value"];

export function readParcel(raw: unknown): Parsed | null {
  const decoded = labelSchema.decode(raw);
  if (!decoded.ok) return null;
  return decoded.value;
}
